//! `blit check` — read-only tree comparison.
//!
//! The comparison algorithm + result types live in
//! `blit_core::check`. This module owns clap-arg handling,
//! filter construction (via `crate::transfers`), the
//! `spawn_blocking` lift, the JSON / text presenters, and the
//! exit-code policy:
//!   - 0 = identical
//!   - 1 = differences found
//!   - 2 = errors

use std::path::PathBuf;
use std::process::ExitCode;

use blit_core::check::{compare_trees, CheckResult};
use blit_core::transfers::filter::{self, FilterInputs};
use eyre::{bail, Context, Result};

use crate::cli::CheckArgs;

pub async fn run_check(args: &CheckArgs) -> Result<ExitCode> {
    let src = PathBuf::from(&args.source);
    let dst = PathBuf::from(&args.destination);
    if !src.exists() {
        bail!("source path does not exist: {}", src.display());
    }
    if !dst.exists() {
        bail!("destination path does not exist: {}", dst.display());
    }

    // EXCLUDE_CASE_MATCHING slice 3b (AC-12): pattern files, read as the
    // transfer verbs read them, into the same lists as the typed patterns.
    let mut exclude = args.exclude.clone();
    let mut include = args.include.clone();
    let from_files = |read: Vec<(String, PathBuf)>| read.into_iter().map(|(pattern, _)| pattern);
    exclude.extend(from_files(
        crate::transfers::read_pattern_files(&args.exclude_from).await?,
    ));
    include.extend(from_files(
        crate::transfers::read_pattern_files(&args.include_from).await?,
    ));

    // audit-19: an absolute `--exclude` under the source is made
    // relative; one that cannot match anything is named, once.
    // cr-g3fix4-1: so is one naming an entry stored under several names.
    let resolved = filter::resolve_excludes(&exclude, Some(&src));
    for pattern in resolved.unmatchable {
        eprintln!(
            "blit: --exclude '{pattern}' cannot match anything under {}",
            src.display()
        );
    }
    for (pattern, patterns) in resolved.expanded {
        eprintln!("{}", filter::shared_entry_note(&pattern, &patterns));
    }

    // Build filter via the same chokepoint that copy/mirror/move use, so
    // `blit check --exclude '*.tmp'` matches `blit copy --exclude '*.tmp'`.
    let filter = filter::build(&FilterInputs {
        include: &include,
        exclude: &exclude,
        files_from: args.files_from.as_ref(),
        retry_only: None,
        retry_only_raw: None,
        source_root: Some(&src),
        ignore_case: args.ignore_case,
        min_size: args.min_size.as_deref(),
        max_size: args.max_size.as_deref(),
        min_age: args.min_age.as_deref(),
        max_age: args.max_age.as_deref(),
    })?;

    let use_checksum = args.checksum;
    let one_way = args.one_way;
    let json = args.json;

    let result = tokio::task::spawn_blocking(move || {
        compare_trees(&src, &dst, use_checksum, one_way, filter)
    })
    .await
    .context("check task panicked")??;

    if json {
        println!("{}", serde_json::to_string_pretty(&result)?);
    } else {
        print_result(&result, one_way);
    }

    if !result.errors.is_empty() {
        Ok(ExitCode::from(2))
    } else if !result.differing.is_empty()
        || !result.missing_on_dest.is_empty()
        || (!one_way && !result.missing_on_src.is_empty())
    {
        Ok(ExitCode::from(1))
    } else {
        Ok(ExitCode::SUCCESS)
    }
}

