    56	/// Compare two local trees with the supplied filter. Synchronous;
    57	/// callers that want to keep the async runtime free should drop
    58	/// this on `spawn_blocking` (the CLI does).
    59	pub fn compare_trees(
    60	    src_root: &Path,
    61	    dst_root: &Path,
    62	    use_checksum: bool,
    63	    one_way: bool,
    64	    filter: FileFilter,
    65	) -> Result<CheckResult> {
    66	    let enumerator = FileEnumerator::new(filter);
    67	
    68	    let src_entries = enumerator
    69	        .enumerate_local(src_root)
    70	        .with_context(|| format!("enumerate source {}", src_root.display()))?;
    71	    let dst_entries = enumerator
    72	        .enumerate_local(dst_root)
    73	        .with_context(|| format!("enumerate destination {}", dst_root.display()))?;
    74	
    75	    let src_map: HashMap<PathBuf, &EnumeratedEntry> = src_entries
    76	        .iter()
    77	        .map(|e| (e.relative_path.clone(), e))
    78	        .collect();
    79	    let dst_map: HashMap<PathBuf, &EnumeratedEntry> = dst_entries
    80	        .iter()
    81	        .map(|e| (e.relative_path.clone(), e))
    82	        .collect();
    83	
    84	    let mut result = CheckResult::default();
    85	
    86	    for src_entry in &src_entries {
    87	        if !matches!(src_entry.kind, EntryKind::File { .. }) {
    88	            continue;
    89	        }
    90	        let rel = &src_entry.relative_path;
    91	        let src_size = match src_entry.kind {
    92	            EntryKind::File { size } => size,
    93	            _ => continue,
    94	        };
    95	
    96	        match dst_map.get(rel) {
    97	            None => {
    98	                result
    99	                    .missing_on_dest
   100	                    .push(rel.to_string_lossy().into_owned());
   101	            }
   102	            Some(dst_entry) => {
   103	                let dst_size = match dst_entry.kind {
   104	                    EntryKind::File { size } => size,
   105	                    _ => {
   106	                        result.differing.push(DiffEntry {
   107	                            path: rel.to_string_lossy().into_owned(),
   108	                            reason: "type mismatch".into(),
   109	                            src_size,
   110	                            dst_size: 0,
   111	                        });
   112	                        continue;
   113	                    }
   114	                };
   115	
   116	                if src_size != dst_size {
   117	                    result.differing.push(DiffEntry {
   118	                        path: rel.to_string_lossy().into_owned(),
   119	                        reason: format!(
   120	                            "size ({} vs {})",
   121	                            format_bytes(src_size),
   122	                            format_bytes(dst_size)
   123	                        ),
   124	                        src_size,
   125	                        dst_size,
   126	                    });
   127	                    continue;
   128	                }
   129	
   130	                if use_checksum {
   131	                    match compare_hashes(&src_entry.absolute_path, &dst_entry.absolute_path) {
   132	                        Ok(true) => result.matching += 1,
   133	                        Ok(false) => result.differing.push(DiffEntry {
   134	                            path: rel.to_string_lossy().into_owned(),
   135	                            reason: "hash mismatch".into(),
   136	                            src_size,
   137	                            dst_size,
   138	                        }),
   139	                        Err(e) => result
   140	                            .errors
   141	                            .push((rel.to_string_lossy().into_owned(), format!("{e:#}"))),
   142	                    }
   143	                } else {
   144	                    let src_mtime = mtime_secs(&src_entry.metadata);
   145	                    let dst_mtime = mtime_secs(&dst_entry.metadata);
   146	                    match (src_mtime, dst_mtime) {
   147	                        (Some(s), Some(d)) if s.abs_diff(d) <= 2 => result.matching += 1,
   148	                        _ => result.differing.push(DiffEntry {
   149	                            path: rel.to_string_lossy().into_owned(),
   150	                            reason: "mtime differs".into(),
   151	                            src_size,
   152	                            dst_size,
   153	                        }),
   154	                    }
   155	                }
   156	            }
   157	        }
   158	    }
   159	
   160	    if !one_way {
   161	        for dst_entry in &dst_entries {
   162	            if !matches!(dst_entry.kind, EntryKind::File { .. }) {
   163	                continue;
   164	            }
   165	            if !src_map.contains_key(&dst_entry.relative_path) {
   166	                result
   167	                    .missing_on_src
   168	                    .push(dst_entry.relative_path.to_string_lossy().into_owned());
   169	            }
   170	        }
   171	    }
   172	
   173	    Ok(result)
   174	}
