   690	/// [`stored_spelling`] of `rest` below `at`.
   691	fn spelled_below(
   692	    at: &Path,
   693	    rest: &[Part],
   694	    windows: bool,
   695	    stored: &impl Fn(&Path) -> Vec<String>,
   696	) -> Vec<Vec<Part>> {
   697	    let Some((part, below)) = rest.split_first() else {
   698	        return vec![Vec::new()];
   699	    };
   700	    let names = match part {
   701	        Part::Literal(name) => vec![name.clone()],
   702	        Part::Typed(component) if has_glob_meta(component, windows) => {
   703	            return vec![rest.to_vec()];
   704	        }
   705	        Part::Typed(component) => {
   706	            let names = stored(&at.join(component));
   707	            if names.is_empty() {
   708	                return vec![rest.to_vec()];
   709	            }
   710	            names
   711	        }
   712	    };
   713	    let mut spelled = Vec::new();
   714	    for name in names {
   715	        for tail in spelled_below(&at.join(&name), below, windows, stored) {
   716	            let mut parts = Vec::with_capacity(rest.len());
   717	            parts.push(Part::Literal(name.clone()));
   718	            parts.extend(tail);
   719	            spelled.push(parts);
   720	        }
   721	    }
   722	    spelled
