   725	/// The names the filesystem stores for `path`'s last component (its own
   726	/// case and Unicode normalization, and on Windows its long name), read
   727	/// without following it: a symlink is named as the link the walk sees,
   728	/// never as its target (cr-g3fix2-1 — resolving the link would name
   729	/// another entry, and leaving it unnamed kept a differently spelled
   730	/// exclude as typed, matching nothing, so a mirror could delete the
   731	/// destination's entry of that name). The names come from the parent
   732	/// directory's listing ([`listed_name`]): one, or every name of the entry
   733	/// when it is hard-linked under several and none is spelled as typed
   734	/// (cr-g3fix4-1). A non-symlink the listing cannot pair (an unreadable
   735	/// listing or identity) falls back to the last component of
   736	/// `canonicalize`. Empty when the path does not exist, or is a symlink the
   737	/// listing cannot pair. `pub(crate)`: the mirror's deletion scope spells
   738	/// its patterns against the destination with it too.
   739	pub(crate) fn stored_name(path: &Path) -> Vec<String> {
   740	    let Ok(metadata) = std::fs::symlink_metadata(path) else {
   741	        return Vec::new();
