   170	/// Pick a port no other test in THIS process has been handed.
   171	///
   172	/// The probe listener is dropped before the daemon binds, so the OS
   173	/// can hand the same port to two parallel tests probing in the same
   174	/// window — the losing daemon exits on "address in use" and its test
   175	/// then talks to the *winner's* daemon (empty/wrong module, spurious
   176	/// failures). Pre-w9-3 the per-test `cargo build` accidentally
   177	/// serialized bring-ups and mostly hid this; the OnceLock build makes
   178	/// parallel probes routine, so uniqueness is enforced with a
   179	/// process-global claimed-set. Cargo runs test binaries sequentially,
   180	/// so per-process uniqueness is exactly the needed scope; collisions
   181	/// with unrelated system processes remain possible but are caught by
   182	/// the child-death check in `spawn_daemon`.
   183	/// Every port handed out in this process — by `pick_unused_port` AND
   184	/// by the fake-server scaffold — goes through this one set, so a fake
   185	/// server can never be assigned a port a daemon was promised (review
   186	/// review of f6e592e caught the fake-server path bypassing the set).
   187	fn claim_port(port: u16) -> bool {
   188	    static CLAIMED: OnceLock<Mutex<HashSet<u16>>> = OnceLock::new();
   189	    CLAIMED
   190	        .get_or_init(|| Mutex::new(HashSet::new()))
   191	        .lock()
   192	        .expect("claimed-port set")
   193	        .insert(port)
   194	}
   195	
   196	pub fn pick_unused_port() -> u16 {
   197	    loop {
   198	        let port = TcpListener::bind(("127.0.0.1", 0))
   199	            .expect("bind probe listener")
   200	            .local_addr()
   201	            .expect("listener addr")
   202	            .port();
   203	        if claim_port(port) {
   204	            return port;
   205	        }
   206	    }
   207	}
