   209	/// Poll until something listens on `127.0.0.1:port` (50 × 100 ms).
   210	///
   211	/// Fake servers own their bound listener before this runs, so a TCP-level
   212	/// readiness check is sufficient for them. Real daemon processes must use
   213	/// [`wait_for_owned_readiness`], which proves application identity as well as a
   214	/// listening socket.
   215	pub fn wait_for_port(port: u16, label: &str) {
   216	    for _ in 0..50 {
   217	        if TcpStream::connect(("127.0.0.1", port)).is_ok() {
   218	            return;
   219	        }
   220	        thread::sleep(Duration::from_millis(100));
   221	    }
   222	    panic!("{label} failed to listen on {port}");
   223	}
