   234	/// Wait for the spawned process to answer a positive identity probe.
   235	///
   236	/// A bare TCP connect can hit a foreign daemon during the probe-to-bind port
   237	/// gap. The process can then lose its bind and exit after the harness has
   238	/// already returned. Keeping the liveness check and the identity probe in one
   239	/// loop prevents that false-ready state.
   240	pub(crate) fn wait_for_owned_readiness(
   241	    attempts: usize,
   242	    pause: Duration,
   243	    mut exited: impl FnMut() -> Result<Option<String>, String>,
   244	    mut identity_matches: impl FnMut() -> bool,
   245	) -> Result<(), String> {
   246	    for attempt in 0..attempts {
   247	        if let Some(status) = exited()? {
   248	            return Err(format!("spawned daemon exited during startup ({status})"));
   249	        }
   250	        if identity_matches() {
   251	            return Ok(());
   252	        }
   253	        if attempt + 1 < attempts {
   254	            thread::sleep(pause);
   255	        }
   256	    }
   257	    Err("spawned daemon did not answer its identity probe".to_string())
   258	}
