'@
$wireSource = @'
use blit_core::fs_enum::FileFilter;
use blit_core::mirror_planner::MirrorPlanner;
use blit_core::remote::transfer::operation_spec::{
    MirrorMode, NormalizedTransferOperation, TransferOperationSpec, SUPPORTED_SPEC_VERSION,
};
use blit_core::transfers::filter::{build, build_spec, FilterInputs};
use std::{collections::HashSet, fs, path::{Path, PathBuf}};

fn main() {
    let fixture = PathBuf::from(std::env::args_os().nth(1).unwrap());
    let files = fixture.join("empty-list.txt");
    let photos = fixture.join("patterns.txt");
    let source = fixture.join("source");
    let destination = fixture.join("destination");
    fs::create_dir(&source).unwrap();
    fs::create_dir(&destination).unwrap();
    fs::write(&files, "# no items\n").unwrap();
    fs::write(&photos, "*.jpg\n").unwrap();
    fs::write(source.join("new.JPG"), "source").unwrap();
    fs::write(destination.join("only.JPG"), "destination").unwrap();
    let includes = FileFilter::load_pattern_file(&photos).unwrap();
    let inputs = FilterInputs {
        include: &includes, exclude: &[], files_from: Some(&files), source_root: Some(&source),
        retry_only: None, retry_only_raw: None, ignore_case: true,
        min_size: None, max_size: None, min_age: None, max_age: None,
    };
    let local = build(&inputs).unwrap();
    let spec = build_spec(&inputs).unwrap();
    let peer = NormalizedTransferOperation::from_spec(TransferOperationSpec {
        spec_version: SUPPORTED_SPEC_VERSION,
        mirror_mode: MirrorMode::FilteredSubset as i32,
        filter: Some(spec),
        ..Default::default()
    }).unwrap().filter.unwrap();
    for (route, filter) in [("local", local), ("peer", peer)] {
        let path = Path::new("new.JPG");
        let send = filter.allows_entry(Some(path), &source.join(path), 6, None);
        let sent = if send { HashSet::from(["new.JPG".to_string()]) } else { HashSet::new() };
        let plan = MirrorPlanner::new(false)
            .plan_session_deletions(&destination, &sent, &[], &HashSet::new(), true, &filter)
            .unwrap();
        let deleted: Vec<_> = plan.files.iter().map(|p| p.file_name().unwrap()).collect();
        println!("{route}: explicit list = {:?}, send new.JPG = {send}, planned deletions = {deleted:?}", filter.files_from);
    }
}
'@
